// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(address adr, bytes memory data, uint256 amount) internal {
        vm.assume(true);
        bool reverted;
        try c.Command(adr, data) { reverted = false; } catch { reverted = true; }
        assertTrue(c.Owner() == address(this) || reverted);
    }

    function testFuzz_run(address adr, bytes memory data, uint256 amount) public {
        vm.assume(adr.code.length == 0 && uint160(adr) > 0xffff && adr != address(this) && adr != address(c) && adr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && adr != 0x000000000000000000636F6e736F6c652e6c6f67 && adr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && adr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(adr, data, amount);
    }

    receive() external payable {}
}
